-- ─────────────────────────────────────────────────────────────────────────────
-- IMPORT DATA
-- Adjust the file path or URL to match your environment.
-- The S3 bucket host below is repeated on each COPY line — SQL has no constant
-- mechanism, so to point at a different bucket find-and-replace this host:
--   iot2-601357753311-eu-west-1-an.s3.eu-west-1.amazonaws.com
-- (the same value lives as the S3_BUCKET constant in the project's Python files).
-- ─────────────────────────────────────────────────────────────────────────────

COPY rtia.plants           FROM 'https://iot2-601357753311-eu-west-1-an.s3.eu-west-1.amazonaws.com/plants.json'  WITH (format = 'json');
COPY rtia.devices          FROM 'https://iot2-601357753311-eu-west-1-an.s3.eu-west-1.amazonaws.com/devices.json'          WITH (format = 'json');
COPY rtia.maintenance_log  FROM 'https://iot2-601357753311-eu-west-1-an.s3.eu-west-1.amazonaws.com/maintenance_log.json'  WITH (format = 'json');
COPY rtia.iot_data         FROM 'https://iot2-601357753311-eu-west-1-an.s3.eu-west-1.amazonaws.com/iot_demo_dataset.json' WITH (format = 'json');

-- ── 5. LOCATIONS ──────────────────────────────────────────────────────────────
-- Reference geometries for geo queries (DISTANCE / WITHIN). Lets the advanced
-- queries look a location up by name instead of hand-coding it inline.
-- location_type is 'point' (a coordinate in geo_location, used with DISTANCE)
-- or 'area' (a polygon in geo_area, used with WITHIN).

CREATE TABLE IF NOT EXISTS rtia.locations (
    location_name   TEXT PRIMARY KEY,
    location_type   TEXT,              -- 'point' | 'area'
    geo_location    GEO_POINT,         -- set when location_type = 'point'
    geo_area        GEO_SHAPE          -- set when location_type = 'area'
);

INSERT INTO rtia.locations (location_name, location_type, geo_location, geo_area) VALUES
    ('Stuttgart', 'point', [9.1819,  48.7843], NULL),   -- PLANT_STUTTGART
    ('Frankfurt', 'point', [8.6638,  50.1071], NULL),   -- Frankfurt (Main) Hauptbahnhof
    ('Munich',    'point', [11.5586, 48.1402], NULL),   -- PLANT_MUNICH
    ('Hamburg',   'point', [10.0068, 53.5528], NULL),   -- PLANT_HAMBURG
    ('Dortmund',  'point', [7.459,   51.5178], NULL),   -- PLANT_DORTMUND
    ('Leipzig',   'point', [12.3815, 51.3454], NULL),   -- PLANT_LEIPZIG
    ('Bavaria',   'area',  NULL, 'POLYGON((10.0 47.3, 13.8 47.3, 13.8 50.6, 10.0 50.6, 10.0 47.3))')
ON CONFLICT (location_name) DO UPDATE SET
    location_type = excluded.location_type,
    geo_location  = excluded.geo_location,
    geo_area      = excluded.geo_area;


-- ── 6. KNN_SEARCHES ───────────────────────────────────────────────────────────
-- Reference query vectors for the VECTOR SEARCH section (KNN_MATCH). Lets a
-- search look its embedding up by name instead of pasting a 384-element literal
-- inline. query_name is the short slug; search_string is the natural-language
-- query the advanced_queries.sql subqueries match on.
-- Embeddings are FLOAT_VECTOR(384) from sentence-transformers/all-MiniLM-L6-v2,
-- precomputed by generate_embeddings.py (normalized).

CREATE TABLE IF NOT EXISTS rtia.knn_searches (
    query_name      TEXT,
    search_string   TEXT PRIMARY KEY,
    embedding       FLOAT_VECTOR(384)
);

